// CUDA kernel for square matrix multiplication with shared memory
__global__ void square_matrix_mul_kernel_shared(const float* A, const float* B, float* C, int N) {
    // Each thread block computes a sub-matrix of C
    // Each thread computes one element of C

    // Define shared memory for A and B tiles
    // The size of the shared memory tiles should match the block size.
    extern __shared__ float shared_A[];
    extern __shared__ float shared_B[];

    // Calculate the base pointers for shared memory for A and B
    // Each block loads a tile of A and a tile of B into shared memory.
    float* As = shared_A;
    float* Bs = shared_B + blockDim.x * blockDim.y; // Offset for B

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    for (int tile = 0; tile < (N + blockDim.x - 1) / blockDim.x; ++tile) {
        // Load tile of A into shared memory
        int tile_row_A = blockIdx.y * blockDim.y + threadIdx.y;
        int tile_col_A = tile * blockDim.x + threadIdx.x;
        if (tile_row_A < N && tile_col_A < N) {
            As[threadIdx.y * blockDim.x + threadIdx.x] = A[tile_row_A * N + tile_col_A];
        } else {
            As[threadIdx.y * blockDim.x + threadIdx.x] = 0.0f; // Pad with zeros
        }

        // Load tile of B into shared memory
        int tile_row_B = tile * blockDim.y + threadIdx.y;
        int tile_col_B = blockIdx.x * blockDim.x + threadIdx.x;
        if (tile_row_B < N && tile_col_B < N) {
            Bs[threadIdx.y * blockDim.x + threadIdx.x] = B[tile_row_B * N + tile_col_B];
        } else {
            Bs[threadIdx.y * blockDim.x + threadIdx.x] = 0.0f; // Pad with zeros
        }
        __syncthreads();

        // Perform matrix multiplication for the current tile
        for (int i = 0; i < blockDim.x; ++i) {
            sum += As[threadIdx.y * blockDim.x + i] * Bs[i * blockDim.x + threadIdx.x];
        }
        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

